class Solution {
    public long gcdOfSums(int n) {
        long k = (n + 1) / 2;
        long oddSum = k * k;

        long m = n / 2;
        long evenSum = m * (m + 1);

        return gcd(oddSum, evenSum);
    }

    private long gcd(long a, long b) {
        while (b != 0) {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}

